function attachGame(){const canvas=document.getElementById('pitch'),ctx=canvas.getContext('2d');const resize=()=>{let r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(canvas.width/1000,0,0,canvas.height/600,0,0)};resize();window.onresize=resize;const controlled=()=>match.players[0];function action(kind){if(!match||!match.running||match.paused)return;let p=controlled(),b=match.ball;if(kind==='pass'||kind==='shoot'){let nearest=match.players.filter(x=>x.side===0&&x!==p).sort((a,c)=>Math.hypot(a.x-b.x,a.y-b.y)-Math.hypot(c.x-b.x,c.y-b.y))[0];if(kind==='pass'){let target=nearest||p;let dx=target.x-b.x,dy=target.y-b.y,l=Math.hypot(dx,dy)||1;b.vx=dx/l*340;b.vy=dy/l*340;match.lastTouch=0;document.getElementById('match-msg').textContent='A crisp pass into space!'}else{let targetX=1000,targetY=300,dx=targetX-b.x,dy=targetY-b.y,l=Math.hypot(dx,dy)||1;b.vx=dx/l*630;b.vy=dy/l*210;match.lastTouch=0;document.getElementById('match-msg').textContent='A powerful strike!'}}}
