function playerDraw(p){let x=p.x,y=p.y,side=p.side,primary=side===0?match.home.color:match.away.color,away=side===1;let running=Math.hypot(p.vx,p.vy)>10,step=running?Math.sin(p.phase)*7:Math.sin(p.phase)*1.5;ctx.save();ctx.translate(x,y);ctx.lineCap='round';ctx.lineJoin='round';// shadow
