function frame(now){if(!match)return;let dt=Math.min(.04,(now-match.lastFrame)/1000||.016);match.lastFrame=now;if(match.running&&!match.paused){match.time+=dt;match.goalFlash=Math.max(0,match.goalFlash-dt);const user=match.players[0],c=match.controls,speed=c['shift']?205:150;let dx=(c['arrowright']||c.d?1:0)-(c['arrowleft']||c.a?1:0),dy=(c['arrowdown']||c.s?1:0)-(c['arrowup']||c.w?1:0),len=Math.hypot(dx,dy)||1;user.vx=dx/len*speed;user.vy=dy/len*speed;user.x=Math.max(42,Math.min(958,user.x+user.vx*dt));user.y=Math.max(62,Math.min(538,user.y+user.vy*dt));user.phase+=dt*12;let b=match.ball;for(let p of match.players){if(p===user)continue;p.phase+=dt*9;let wantsBall=p.side===1||(!user.hasBall&&p.side===0),targetX=wantsBall?b.x:(p.side===0?410:590)+(p.index%3-1)*80,targetY=wantsBall?b.y:100+Math.floor(p.index/3)*340+(p.index%2)*55,ddx=targetX-p.x,ddy=targetY-p.y,ll=Math.hypot(ddx,ddy)||1,sp=wantsBall?100:43;p.vx=ddx/ll*sp;p.vy=ddy/ll*sp;p.x+=p.vx*dt;p.y+=p.vy*dt;if(wantsBall&&Math.hypot(b.x-p.x,b.y-p.y)<15&&Math.random()<dt*1.1){b.vx=(p.side===0?1:-1)*145;b.vy=(Math.random()-.5)*95;match.lastTouch=p.side}}
