function togglePause(){if(!match)return;match.paused=!match.paused;const b=document.querySelector('[data-action="pause"]');if(b)b.innerHTML=match.paused?'▶ &nbsp; RESUME':'Ⅱ &nbsp; PAUSE'}
function squads(){page='squads';let roster=[['K. Navas','GK','30'],['D. Carvajal','RB','2'],['S. Ramos','CB','4'],['Pepe','CB','3'],['Marcelo','LB','12'],['Casemiro','CDM','14'],['T. Kroos','CM','8'],['L. Modrić','CM','19'],['G. Bale','RW','11'],['K. Benzema','ST','9'],['Cristiano Ronaldo','LW','7'],['K. C.','GK','13'],['Isco','CAM','22'],['J. Rodríguez','CAM','10'],['Morata','ST','21']];app.innerHTML=`${header('SQUADS')}<main class="main"><div class="screen-title"><div><div class="eyebrow">TEAM MANAGEMENT</div><h1>Squad room.</h1><p class="muted">Explore teams, lineups and player ratings.</p></div><button class="secondary" data-action="back">← &nbsp; MAIN MENU</button></div><div class="form-row"><div class="panel"><div class="field-label">CHOOSE A TEAM</div><select class="select" id="squad-team">${teams.map((t,i)=>`<option value="${i}" ${i===2?'selected':''}>${t.name}</option>`).join('')}</select><div style="font-size:52px;color:var(--lime);margin:28px 0 8px" id="squad-crest">${teams[2].crest}</div><h2 id="squad-name" style="margin:0">${teams[2].name}</h2><p class="muted" style="font-size:11px">Starting XI · 4-3-3 · Overall 86</p><div class="feature-tag">HOME KIT &nbsp; ▰ &nbsp; AWAY KIT &nbsp; ▰</div></div><div class="panel"><div class="field-label">STARTING XI &nbsp; · &nbsp; 4-3-3</div><div style="display:grid;grid-template-columns:1fr 50px 35px;gap:8px;margin-top:12px;color:#8599ad;font-size:9px;font-weight:900;letter-spacing:1px"><span>PLAYER</span><span>POS</span><span>OVR</span></div>${roster.slice(0,11).map((p,i)=>`<div style="display:grid;grid-template-columns:1fr 50px 35px;gap:8px;padding:10px 0;border-bottom:1px solid #ffffff12;font-size:11px"><span>${i<11?'★':'·'} &nbsp; ${p[0]}</span><span class="muted">${p[1]}</span><b style="color:${i===10?'var(--lime)':'#d9e3eb'}">${93-i*2}</b></div>`).join('')}<button class="secondary" style="margin-top:14px" data-action="edit">✎ &nbsp; EDIT LINEUP</button></div></div><section class="panel" style="margin-top:14px"><div class="field-label">SQUAD DEPTH &nbsp; · &nbsp; SUBSTITUTES</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:12px">${roster.slice(11).map(p=>`<div class="choice" style="min-width:145px;text-align:left">${p[0]} <span class="muted" style="float:right">${p[1]} · ${78+Math.round(Math.random()*9)}</span></div>`).join('')}</div></section><div class="page-actions"><span class="muted" style="font-size:10px">12 FEATURED CLUBS · 3 NATIONAL TEAMS</span><button class="primary" data-action="kickoff">PLAY WITH THIS TEAM &nbsp; →</button></div></main>${footer()}`;bindCommon();document.getElementById('squad-team').onchange=e=>{let t=teams[+e.target.value];document.getElementById('squad-name').textContent=t.name;document.getElementById('squad-crest').textContent=t.crest;document.getElementById('squad-crest').style.color=t.color}}
function customise(){page='customise';app.innerHTML=`${header('CUSTOMISE')}<main class="main"><div class="screen-title"><div><div class="eyebrow">MAKE IT YOUR GAME</div><h1>Make it yours.</h1><p class="muted">Your club. Your colors. Your football.</p></div><button class="secondary" data-action="back">← &nbsp; MAIN MENU</button></div><div class="mode-grid">${[['✎','Edit Player','Name, number, position and attributes.'],['⚑','Create a Club','Choose your badge colors and home ground.'],['⇄','Transfers','Move players to build your dream squad.'],['⚙','Match Settings','Tune difficulty, audio and game speed.'],['◈','Kits & Boots','Choose your home and away look.'],['▤','Tactics','Formation, lineup and team strategy.']].map((x,i)=>`<button class="mode-card" data-action="custom-${i}"><div class="mode-icon">${x[0]}</div><b>${x[1]}</b><span>${x[2]}</span><span style="color:var(--lime);font-weight:900;margin-top:16px">CUSTOMISE &nbsp; →</span></button>`).join('')}</div><div class="panel" style="margin-top:18px"><div class="eyebrow">GAME SETTINGS</div><div class="form-row"><div><div class="field-label">COMMENTARY LANGUAGE</div><select class="select" id="commentary"><option>English</option><option>Português</option><option>Español</option></select></div><div><div class="field-label">MATCH LENGTH</div><select class="select" id="half-length"><option>3 minute halves</option><option>5 minute halves</option><option>6 minute halves</option></select></div></div></div></main>${footer()}`;bindCommon()}
function settingsPage(){showToast(settings.sound?'AUDIO ON · '+settings.difficulty.toUpperCase():'AUDIO OFF · '+settings.difficulty.toUpperCase())}
function showToast(msg){document.querySelector('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.textContent=msg;document.body.appendChild(d);clearTimeout(toastTimer);toastTimer=setTimeout(()=>d.remove(),2600)}
function bindCommon(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{let x=b.dataset.nav;if(x==='HOME')home();if(x==='PLAY')modePage('modes');if(x==='SQUADS')squads();if(x==='CUSTOMISE')customise()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action));document.querySelectorAll('[data-mode],[data-pick]').forEach(b=>b.onclick=()=>{if(b.dataset.mode==='kickoff'||b.dataset.pick==='kickoff')kickoff();else if(b.dataset.mode==='training'||b.dataset.pick==='training')startMatch(0,1);else modePage(b.dataset.mode||'modes')});let lang=document.getElementById('language');if(lang)lang.onchange=()=>{language=lang.value;page==='home'?home():page==='kickoff'?kickoff():page==='squads'?squads():page==='customise'?customise():page==='match'?renderMatch():modePage(page)}}
function handle(a){if(a==='kickoff')kickoff();else if(a==='modes')modePage('modes');else if(a==='career'||a==='ultimate'||a==='tournament'||a==='seasons'||a==='training')modePage(a);else if(a==='back')home();else if(a==='settings')settingsPage();else if(a==='pause')togglePause();else if(a==='quit'){if(confirm('Quit this match and return to setup?'))kickoff()}else if(a==='edit')showToast('LINEUP EDITOR · Select a player to change position');else if(a.startsWith('custom-')){const i=+a.split('-')[1];if(i===3){settings.sound=!settings.sound;showToast('MATCH SETTINGS · AUDIO '+(settings.sound?'ON':'OFF'))}else showToast(['PLAYER EDITOR · Customize name, number and attributes','CLUB CREATOR · Choose colors and stadium','TRANSFER CENTRE · Squad transfers opened','MATCH SETTINGS · Professional difficulty','KIT ROOM · Home and away kits','TACTICS BOARD · 4-3-3 formation'][i])}}
home();
})();
</script></body></html>

