const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage({viewport:{width:1280,height:800}});
 const errors=[];
 page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:3002',{waitUntil:'load'});
 await page.waitForTimeout(300);
 const results=[];
 async function check(name,fn){try{await fn();results.push(`${name}: PASS`)}catch(e){results.push(`${name}: FAIL ${e.message}`)}}
 await check('Home',async()=>{await page.locator('[data-nav="HOME"]').waitFor(); if(await page.locator('.hero').count()!=1)throw Error('hero missing')});
 await check('Kick Off setup',async()=>{await page.getByRole('button',{name:/PLAY MATCH/i}).click();await page.locator('#start-match').waitFor()});
 await check('Local 2P setup',async()=>{await page.getByRole('button',{name:'LOCAL 2P'}).click();await page.locator('[data-type="local"].selected').waitFor()});
 await check('Match launch',async()=>{await page.locator('#start-match').click();await page.locator('#pitch').waitFor();await page.waitForTimeout(1200);const clock=await page.locator('#clock').textContent();if(clock==='00:00')throw Error('clock not advancing')});
 await check('P1 WASD + shoot',async()=>{await page.keyboard.down('w');await page.waitForTimeout(150);await page.keyboard.up('w');await page.keyboard.press(' ');await page.keyboard.press('q')});
 await check('P2 arrows + pass/shoot',async()=>{await page.keyboard.down('ArrowRight');await page.waitForTimeout(150);await page.keyboard.up('ArrowRight');await page.keyboard.press('e');await page.keyboard.down('Shift');await page.waitForTimeout(100);await page.keyboard.up('Shift')});
 await check('Pause',async()=>{await page.keyboard.press('Escape');await page.getByText('MATCH PAUSED').waitFor({state:'visible'})});
 await page.keyboard.press('Escape');
 await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/final-match.jpg',type:'jpeg',quality:88});
 await check('Quit setup',async()=>{page.once('dialog',d=>d.accept());await page.getByRole('button',{name:/QUIT MATCH/i}).click();await page.locator('#start-match').waitFor()});
 for(const lang of ['PT','ES','EN']){
  await check(`Language ${lang}`,async()=>{await page.selectOption('#language',lang);await page.waitForTimeout(100);if(await page.locator('#language').inputValue()!=lang)throw Error('select did not switch')});
 }
 await check('All top navigation',async()=>{for(const nav of ['SQUADS','CUSTOMISE','PLAY','HOME']){await page.locator(`[data-nav="${nav}"]`).click();await page.waitForTimeout(80)}});
 await check('Expanded mode pages',async()=>{await page.getByRole('button',{name:/EXPLORE MODES/i}).click();for(const name of ['Career Mode','Ultimate Team','Tournaments','Seasons','Training Ground','Game Modes']){await page.waitForTimeout(40)}});
 await page.locator('[data-nav="HOME"]').click();
 await page.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/final-home.jpg',type:'jpeg',quality:88});
 const mobile=await browser.newPage({viewport:{width:390,height:844}});
 mobile.on('pageerror',e=>errors.push('mobile:'+e.message));
 await mobile.goto('http://localhost:3002',{waitUntil:'load'});await mobile.waitForTimeout(300);
 await check('Mobile home',async()=>{if(await mobile.locator('.hero').count()!=1)throw Error('mobile hero missing')});
 await mobile.screenshot({path:'/home/runner/work/PlayGround/PlayGround/screenshots/final-mobile.jpg',type:'jpeg',quality:88});
 await check('Mobile kickoff',async()=>{await mobile.getByRole('button',{name:/PLAY MATCH/i}).click();await mobile.locator('#start-match').waitFor()});
 console.log(results.join('\n'));console.log('PAGE ERRORS:',errors.length?errors.join(' | '):'none');
 await browser.close();
 if(errors.length||results.some(r=>r.includes('FAIL')))process.exit(1);
})();

